/**
 * Automated Result Extraction Script for Batch CLI Outputs
 * Parses kits.json generated by `npm run evaluate` and extracts
 * structured outputs: Questions, Anki Flashcard TSVs, and Coverage Summaries.
 */

import fs from 'fs';
import path from 'path';
import { parseArgs } from 'util';
import { BatchOutputPayload } from '../src/core/types';

async function main() {
  const { values } = parseArgs({
    args: process.argv.slice(2),
    options: {
      input: { type: 'string', short: 'i' },
      output: { type: 'string', short: 'o' },
      format: { type: 'string', short: 'f' }, // 'questions' | 'anki' | 'requirements' | 'markdown' | 'all'
      priority: { type: 'string', short: 'p' }, // 'must' | 'all'
      help: { type: 'boolean', short: 'h' },
    },
    strict: false,
    allowPositionals: true,
  });

  if (values.help) {
    console.log(`
Automated Result Extraction CLI
Extracts questions, Anki flashcard TSVs, or Markdown study briefs from Batch CLI evaluate output.

Usage:
  npm run extract-results -- --input kits.json [options]

Options:
  --input, -i       Path to output JSON file generated by evaluate (Default: kits.json)
  --output, -o      Output destination file or directory
  --format, -f      Extraction target: questions | anki | requirements | markdown | all (Default: all)
  --priority, -p    Filter by question priority: must | all (Default: all)
  --help, -h        Show this help message

Examples:
  npm run extract-results -- --input kits.json --format anki --output flashcards.tsv
  npm run extract-results -- --input kits.json --format questions --priority must
  npm run extract-results -- --input kits.json --format all --output ./extracted_kits/
    `);
    process.exit(0);
  }

  const inputPath = (values.input as string) || 'kits.json';
  const format = ((values.format as string) || 'all').toLowerCase();
  const priorityFilter = (values.priority as string) || 'all';
  const outputPath = values.output as string | undefined;

  const resolvedInput = path.resolve(process.cwd(), inputPath);
  if (!fs.existsSync(resolvedInput)) {
    console.error(`Error: Input file not found at ${resolvedInput}`);
    console.error('Run "npm run evaluate -- --input cases.json --output kits.json" first.');
    process.exit(1);
  }

  const raw = fs.readFileSync(resolvedInput, 'utf-8');
  let payload: BatchOutputPayload;
  try {
    payload = JSON.parse(raw);
  } catch (err: any) {
    console.error(`Error parsing JSON: ${err.message}`);
    process.exit(1);
  }

  const successfulKits = (payload.kits || []).filter((k) => k.status === 'ok' && k.kit);
  if (successfulKits.length === 0) {
    console.warn('Warning: No successful kits found in payload.');
    process.exit(0);
  }

  console.log(`\n[Result Extractor] Found ${successfulKits.length} successful kit(s) in ${inputPath}`);

  // Helper to determine if question is linked to a 'must' requirement
  const getQuestionPriority = (kit: any, question: any): 'must' | 'nice' => {
    const mustReqIds = new Set(
      (kit.role?.requirements || [])
        .filter((r: any) => r.priority === 'must')
        .map((r: any) => r.id)
    );
    const hasMust = (question.requirement_ids || []).some((id: string) => mustReqIds.has(id));
    return hasMust || question.difficulty >= 2 ? 'must' : 'nice';
  };

  // 1. EXTRACT QUESTIONS
  if (format === 'questions' || format === 'all') {
    let questionRows: string[] = ['Company\tRole\tPriority\tCategory\tQuestion\tAnswer Outline'];
    successfulKits.forEach(({ kit }) => {
      if (!kit) return;
      kit.questions.forEach((q) => {
        const priority = getQuestionPriority(kit, q);
        if (priorityFilter !== 'all' && priority !== priorityFilter) return;
        const cleanPrompt = (q.prompt || '').replace(/"/g, '""');
        const cleanOutline = (q.answer_outline || '').replace(/"/g, '""').replace(/\n/g, ' ');
        questionRows.push(
          `${kit.source.company}\t${kit.role.title}\t${priority.toUpperCase()}\t${q.category}\t"${cleanPrompt}"\t"${cleanOutline}"`
        );
      });
    });

    const questionsTsv = questionRows.join('\n');
    if (format === 'questions') {
      if (outputPath) {
        fs.writeFileSync(path.resolve(process.cwd(), outputPath), questionsTsv, 'utf-8');
        console.log(`✓ Questions exported to ${outputPath} (${questionRows.length - 1} questions)`);
      } else {
        console.log('\n--- EXTRACTED QUESTIONS (TSV) ---');
        console.log(questionsTsv);
      }
    }
  }

  // 2. EXTRACT ANKI FLASHCARDS
  if (format === 'anki' || format === 'all') {
    let ankiCards: string[] = [];
    successfulKits.forEach(({ kit }) => {
      if (!kit) return;
      kit.flashcards.forEach((card) => {
        const cleanFront = card.front.replace(/\t/g, ' ').replace(/\n/g, '<br>');
        const cleanBack = card.back.replace(/\t/g, ' ').replace(/\n/g, '<br>');
        const tags = `${kit.source.company.toLowerCase()} ${kit.role.title.toLowerCase().replace(/\s+/g, '_')}`;
        ankiCards.push(`${cleanFront}\t${cleanBack}\t${tags}`);
      });
    });

    const ankiTsv = ankiCards.join('\n');
    if (format === 'anki') {
      if (outputPath) {
        fs.writeFileSync(path.resolve(process.cwd(), outputPath), ankiTsv, 'utf-8');
        console.log(`✓ Anki cards exported to ${outputPath} (${ankiCards.length} cards)`);
      } else {
        console.log('\n--- ANKI IMPORT READY TSV (Front <TAB> Back <TAB> Tags) ---');
        console.log(ankiTsv);
      }
    }
  }

  // 3. EXTRACT REQUIREMENTS AUDIT
  if (format === 'requirements' || format === 'all') {
    let reqRows: string[] = ['Company\tRole\tPriority\tRequirement'];
    successfulKits.forEach(({ kit }) => {
      if (!kit) return;
      kit.role.requirements.forEach((req) => {
        reqRows.push(
          `${kit.source.company}\t${kit.role.title}\t${req.priority.toUpperCase()}\t"${req.text.replace(/"/g, '""')}"`
        );
      });
    });

    const reqTsv = reqRows.join('\n');
    if (format === 'requirements') {
      if (outputPath) {
        fs.writeFileSync(path.resolve(process.cwd(), outputPath), reqTsv, 'utf-8');
        console.log(`✓ Requirements exported to ${outputPath} (${reqRows.length - 1} requirements)`);
      } else {
        console.log('\n--- REQUIREMENTS AUDIT MATRIX ---');
        console.log(reqTsv);
      }
    }
  }

  // 4. FORMAT ALL (DUMP DIRECTORY OR DEFAULT FILES)
  if (format === 'all') {
    const targetDir = outputPath ? path.resolve(process.cwd(), outputPath) : path.resolve(process.cwd(), 'extracted_results');
    if (!fs.existsSync(targetDir)) {
      fs.mkdirSync(targetDir, { recursive: true });
    }

    // Write Questions TSV
    const qRows = ['Company\tRole\tPriority\tCategory\tQuestion\tAnswer Outline'];
    successfulKits.forEach(({ kit }) => {
      if (!kit) return;
      kit.questions.forEach((q) => {
        const priority = getQuestionPriority(kit, q);
        qRows.push(
          `${kit.source.company}\t${kit.role.title}\t${priority.toUpperCase()}\t${q.category}\t"${(q.prompt || '').replace(/"/g, '""')}"\t"${(q.answer_outline || '').replace(/"/g, '""').replace(/\n/g, ' ')}"`
        );
      });
    });
    fs.writeFileSync(path.join(targetDir, 'all_questions.tsv'), qRows.join('\n'), 'utf-8');

    // Write Anki TSV
    const ankiRows: string[] = [];
    successfulKits.forEach(({ kit }) => {
      if (!kit) return;
      kit.flashcards.forEach((card) => {
        ankiRows.push(`${card.front.replace(/\n/g, '<br>')}\t${card.back.replace(/\n/g, '<br>')}\t${kit.source.company}`);
      });
    });
    fs.writeFileSync(path.join(targetDir, 'anki_flashcards.tsv'), ankiRows.join('\n'), 'utf-8');

    // Write Markdown Study Guide
    let mdContent = `# Consolidated Multi-Kit Interview Preparation\nGenerated: ${new Date().toISOString()}\n\n`;
    successfulKits.forEach(({ kit }) => {
      if (!kit) return;
      mdContent += `## ${kit.source.company} - ${kit.role.title}\n`;
      mdContent += `**Source**: ${kit.source.company_url || 'Direct JD'} | **Timeline**: ${kit.schedule.days_available} Days\n\n`;
      mdContent += `### Company Brief\n${kit.company_brief.summary}\n\n`;
      mdContent += `### High-Priority Questions\n`;
      kit.questions.forEach((q, idx) => {
        const priority = getQuestionPriority(kit, q);
        if (priority === 'must') {
          mdContent += `${idx + 1}. **[${q.category}]** ${q.prompt}\n   *Outline*: ${q.answer_outline}\n\n`;
        }
      });
      mdContent += `\n---\n\n`;
    });
    fs.writeFileSync(path.join(targetDir, 'study_guide.md'), mdContent, 'utf-8');

    console.log(`\n✓ All results automatedly extracted into ${targetDir}:`);
    console.log(`  - all_questions.tsv (${qRows.length - 1} questions)`);
    console.log(`  - anki_flashcards.tsv (${ankiRows.length} flashcards)`);
    console.log(`  - study_guide.md (Complete Markdown Study Guide)`);
    console.log(`\nImport anki_flashcards.tsv into Anki via File -> Import -> Tab-separated.`);
  }
}

main().catch((err) => {
  console.error('Fatal error during extraction:', err);
  process.exit(1);
});
